package com.vandorlabs.neoforge.propulsion;
import com.vandorlabs.neoforge.redstone.*;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Private inactive placed engines and complete-process restart, not public activation. */
@EventBusSubscriber(modid="vandorlabs")
public final class PropulsionHostChecks {
 private static final BlockPos BASE=new BlockPos(7204,80,7204),COLD=new BlockPos(7296,80,7296);private static NativePropulsionBlock BLOCK;private static BlockEntityType<NativePropulsionEntity> TYPE;private static int checks;
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("propulsion-host-");}private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Propulsion host "+text);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{BLOCK=new NativePropulsionBlock("rocket_thruster",BlockBehaviour.Properties.of().strength(3),()->TYPE);h.register(ResourceLocation.parse("vandorlabs:propulsion_host_fixture"),BLOCK);});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativePropulsionEntity(TYPE,p,s),BLOCK).build(null);h.register(ResourceLocation.parse("vandorlabs:propulsion_host_fixture"),TYPE);});}}
 private static NativePropulsionEntity at(ServerLevel w,BlockPos p){return (NativePropulsionEntity)w.getBlockEntity(p);}
 private static NativePropulsionEntity put(ServerLevel w,BlockPos p,CompoundTag tag){w.getChunkAt(p);w.setBlock(p,BLOCK.defaultBlockState(),18);var owner=at(w,p);owner.loadWithComponents(tag,w.registryAccess());owner.onLoad();return owner;}
 private static CompoundTag settings(int particle,boolean analog){var tag=new CompoundTag();tag.putBoolean("ManualOn",true);tag.putBoolean("LightInitialized",true);tag.putBoolean("SignalBrightness",analog);tag.putInt("ParticleLevel",particle);tag.putString("FutureEngine","opaque:engine");var caps=new CompoundTag();caps.putString("Owner","opaque:cap");tag.put("ForgeCaps",caps);return tag;}
 private static void write(ServerLevel w){var a=put(w,BASE,settings(0,false));var b=put(w,BASE.east(),settings(0,false));var c=put(w,BASE.above(),settings(0,false));var d=put(w,BASE.east().above(),settings(0,false));NativePropulsionService.refresh(a);need(a.visual().part().size()==2&&d.visual().part().x()==1&&d.visual().part().y()==1,"actual prepared2x2 source plane");need(a.visual().powered()&&a.visual().brightness()==15,"captured Source default operating state");var actor=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("efb1ae4d-6cb6-4b6b-8ba6-84e5bb90d735"),"PropulsionHost"));actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setPos(BASE.getX(),BASE.getY(),BASE.getZ());need(d.manualUse(actor)&&a.visual().selected()&&b.visual().particleLevel()==1,"bottom-left mode1to2 all members");need(b.manualUse(actor)&&!a.visual().powered()&&!d.visual().selected(),"mode2to0 all members");need(a.manualUse(actor)&&a.visual().powered()&&!c.visual().selected(),"mode0to1 all members");
  var snapshot=a.visual();var data=a.getModelData();NativePropulsionService.refresh(a);need(a.visual()==snapshot&&a.getModelData()==data,"unchanged refresh keeps worker publication identity");long before=allocated();for(int n=0;n<100000;n++){if(a.getModelData()!=data||a.visual()!=snapshot)throw new AssertionError("worker publication");}need(allocated()-before<4096,"100000 worker reads no allocation");
  var numeric=put(w,BASE.south(4),settings(3,true));w.setBlock(numeric.getBlockPos().south(),Blocks.REDSTONE_BLOCK.defaultBlockState(),18);NativePropulsionService.refresh(numeric);need(numeric.visual().brightness()==15&&numeric.visual().powered()&&numeric.visual().selected(),"actual physical analog maximum");w.setBlock(numeric.getBlockPos().south(),Blocks.AIR.defaultBlockState(),18);NativePropulsionService.refresh(numeric);need(!numeric.visual().powered()&&!numeric.visual().selected(),"physical loss settles");numeric.setChannelLevel(7);NativePropulsionService.flush(w);need(numeric.visual().powered()&&numeric.visual().brightness()==7&&!numeric.visual().selected(),"channel analog7 below threshold8");numeric.setChannelLevel(8);NativePropulsionService.flush(w);need(numeric.visual().selected(),"channel threshold8");
  var cold=put(w,COLD,settings(2,false));need(!NativePropulsionService.loaded(w,COLD.west())&&!NativePropulsionService.loaded(w,COLD.north()),"cold neighbors absent");cold.onLoad();NativePropulsionService.refresh(cold);need(!NativePropulsionService.loaded(w,COLD.west())&&!NativePropulsionService.loaded(w,COLD.north())&&cold.visual().part().size()==1,"local onLoad and partition fallback never load cold neighbors");
  var bad=settings(3,true);bad.putInt("NativePropulsionSchema",99);var failed=put(w,BASE.south(8),bad);NativePropulsionService.refresh(failed);need(failed.inert()&&!failed.visual().powered()&&failed.saveWithoutMetadata(w.registryAccess()).equals(bad),"future schema retains exact inert snapshot");var update=a.getUpdateTag(w.registryAccess());need(!update.contains("ForgeCaps")&&!update.contains("FutureEngine"),"public projection excludes private opaque fields");need(a.saveWithoutMetadata(w.registryAccess()).getCompound("ForgeCaps").getString("Owner").equals("opaque:cap"),"valid opaque ownership retained");
  b.onChunkUnloaded();NativePropulsionService.refresh(a);need(a.visual().part().size()==1,"retired member breaks prepared square");b.onLoad();NativePropulsionService.refresh(a);need(a.visual().part().size()==2,"deferred load rejoins");w.setChunkForced(BASE.getX()>>4,BASE.getZ()>>4,true);w.setChunkForced(BASE.getX()>>4,(BASE.getZ()+8)>>4,true);
 }
 private static long allocated(){var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);return meter.getThreadAllocatedBytes(Thread.currentThread().threadId());}
 private static void read(ServerLevel w){w.getChunkAt(BASE);var a=at(w,BASE);NativePropulsionService.refresh(a);need(a!=null&&a.visual().powered()&&a.visual().part().size()==2&&!a.visual().selected(),"complete-process saved operating/partition state");need(a.saveWithoutMetadata(w.registryAccess()).getCompound("ForgeCaps").getString("Owner").equals("opaque:cap"),"restart retains opaque owner");var failed=at(w,BASE.south(8));need(failed!=null&&failed.inert()&&failed.saveWithoutMetadata(w.registryAccess()).getInt("NativePropulsionSchema")==99,"restart inert schema");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;try{var w=e.getServer().overworld();if(phase().endsWith("write"))write(w);else read(w);e.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][propulsion-host] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);}catch(Throwable failure){System.err.println("[vandorlabs][propulsion-host] FAIL "+failure);failure.printStackTrace();}finally{e.getServer().halt(false);}}
}
